<template><view class="page"><text class="title">帮助与反馈</text><view class="card"><view v-for="q in faqs" :key="q.q" class="faq" @tap="q.open=!q.open"><view class="head"><text class="q">{{q.q}}</text><text>⌄</text></view><text v-if="q.open" class="a">{{q.a}}</text></view></view><text class="label">意见反馈</text><textarea v-model="feedback" class="textarea" placeholder="告诉我们哪里不好用，或希望增加什么功能"/><button class="save" @tap="submit">保存反馈</button><text class="tip">当前反馈仅保存在本机，待反馈接口上线后再提交到服务端。</text></view></template><script>export default{data(){return{feedback:'',faqs:[{q:'长辈端怎么使用？',a:'家人先添加长辈并发送邀请。长辈打开邀请后点击“接受邀请”，无需注册账号。',open:false},{q:'如何添加长辈？',a:'进入家人端“我的”，点击“添加长辈”，填写资料后生成邀请。',open:false},{q:'为什么没有微信通知？',a:'真实微信订阅消息尚未接入，目前系统只记录相关业务事件，不会声称已经通知家人。',open:false}]}},methods:{submit(){if(!this.feedback.trim())return uni.showToast({title:'请先填写反馈',icon:'none'});uni.setStorageSync('suilin_feedback_draft',this.feedback.trim());this.feedback='';uni.showToast({title:'已保存在本机',icon:'success'})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#fff9f2}.title{display:block;font-size:40rpx;font-weight:900;color:#493a33;margin-bottom:24rpx}.card{padding:0 24rpx;background:#fff;border-radius:28rpx}.faq{padding:24rpx 0;border-bottom:1rpx solid #f0e7df}.head{display:flex;justify-content:space-between}.q{font-size:25rpx;font-weight:800}.a{display:block;margin-top:12rpx;color:#88776c;font-size:21rpx;line-height:1.7}.label{display:block;margin:30rpx 0 12rpx;font-size:25rpx;font-weight:800}.textarea{width:100%;height:220rpx;box-sizing:border-box;padding:22rpx;background:#fff;border-radius:24rpx}.save{margin-top:22rpx;background:#2fa99a;color:#fff;border-radius:20rpx}.tip{display:block;margin-top:12rpx;color:#9b887d;font-size:20rpx;line-height:1.5}</style>